{"content":"688|fn seal_plugins(dir: &Path) -> Result<(), String> {
689|    op_plugins::state_plugins::threetched::prepare_schema_capture()
690|        .map_err(|error| format!("capture threetched schema before sealing: {error:#}"))?;
691|    std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
692|    let mut cat = ActiveReflectionCatalog::open(dir).map_err(|e| e.to_string())?;
693|    let rt = tokio::runtime::Builder::new_current_thread()
694|        .enable_all()
695|        .build()
696|        .map_err(|e| e.to_string())?;
697|    let registry = DefaultPluginRegistry::new(Arc::new(MemoryStore::new()));
698|    let plugins = rt
699|        .block_on(registry.load_all_plugins())
700|        .map_err(|e| e.to_string())?;
701|
702|    let mut sealed = 0usize;
703|    let mut sealed_ids = std::collections::HashSet::new();
704|    let mut missing_schema = Vec::new();
705|    for plugin in plugins {
706|        let plugin_id = plugin.name().to_string();
707|        // Prefer a live-probed schema (real backend reachability folded in)
708|        // over the static declaration; most plugins have nothing to probe
709|        // and schema_live() defaults to None, in which case schema() is used.
710|        let live = rt.block_on(plugin.schema_live());
711|        let schema = match live.or_else(|| plugin.schema()) {
712|            Some(schema) => schema,
713|            None => {
714|                missing_schema.push(plugin_id);
715|                continue;
716|            }
717|        };
718|        let blob = blobify_plugin_schema(&plugin_id, schema);
719|        sealed_ids.insert(blob.manifest.plugin_id.clone());
720|        let path = cat.upsert_blob(&blob).map_err(|e| e.to_string())?;
721|        println!(
722|            "sealed    {}  ({} methods, schema {})",
723|            path.display(),
724|            blob.manifest.methods.len(),
725|            &blob.manifest.schema_hash[..16]
726|        );
727|        sealed += 1;
728|    }
729|
730|    // A blob in the catalog IS the plugin: sweep blobs whose plugin no
731|    // longer exists in the build (deregistration by disappearance).
732|    let mut swept = cat.retain_plugins(&sealed_ids).map_err(|e| e.to_string())?;
733|    swept.sort();
734|    for plugin_id in &swept {
735|        println!("swept     {plugin_id} (plugin no longer exists)");
736|    }
737|
738|    println!("catalog   {}", dir.display());
739|    println!("hash      {}", cat.catalog_hash());
740|    println!("sealed    {sealed} plugin blobs");
741|    if !missing_schema.is_empty() {
742|        missing_schema.sort();
743|        println!("skipped   {} plugins without schema", missing_schema.len());
744|        for plugin_id in missing_schema {
745|            println!("  {plugin_id}");
746|        }
747|    }
748|    println!("services:");
749|    for s in cat.list_services() {
750|        println!("  {s}");
751|    }
752|    Ok(())
